def case(i,title,de,en,taskd,taske,sold,sole,fd,fe,fsd,fse,criteria):
 return dict(id=i,titleDe=title[0],titleEn=title[1],syntheticData=True,actualExperimentPerformed=False,materialDe=de,materialEn=en,taskDe=taskd,taskEn=taske,workedSolutionDe=sold,workedSolutionEn=sole,freshTransferDe=fd,freshTransferEn=fe,freshTransferSolutionDe=fsd,freshTransferSolutionEn=fse,limitsDe='Fiktive Unterrichtsmaterialien; keine persönlichen Angaben, Diagnose, Behandlung, tatsächliche Erprobung oder gemessene Lernleistung. Risiken und Entwicklung sind individuell; die Begründung zählt, kein moralisches oder körperliches Ideal.',limitsEn='Fictional teaching material; no personal disclosure, diagnosis, treatment, actual trial or measured learner performance. Risks and development vary individually; reasoning matters, not a moral or physical ideal.',rubric={'totalPoints':10,'criteria':[dict(id=i+'-r'+str(n+1),points=[4,4,2][n],criterionDe=c[0],criterionEn=c[1]) for n,c in enumerate(criteria)],'masteryClaim':'AUTHOR candidate rubric only; no learner performance, human approval or trial established.'})
def row(prefix,archetype,expectations,axes,cases,atomic):
 g=next(g for g in GOALS if g['id'].startswith(prefix));gid=g['id']
 exp=[dict(id='e'+str(n+1),essentialUnderstandingDe=x[0],essentialUnderstandingEn=x[1],observablePerformanceDe=x[2],observablePerformanceEn=x[3]) for n,x in enumerate(expectations)]
 profile=dict(archetype=archetype,expectations=exp,coverageExpectations=dict(requiredExpectationIds=[x['id'] for x in exp],alternativeExpectationGroups=[],minimumIndependentDemonstrations=2,freshVariationRequired=True,independentTransferRequired=True),variationAxes=[dict(id='v'+str(n+1),textDe=a[0],textEn=a[1]) for n,a in enumerate(axes)],applicationCaseBriefs=[dict(id=c['id'],taskDemandDe=c['taskDe'],taskDemandEn=c['taskEn'],expectedPerformanceDe=c['workedSolutionDe'],expectedPerformanceEn=c['workedSolutionEn'],understandingFocusDe='; '.join(x[0] for x in expectations),understandingFocusEn='; '.join(x[1] for x in expectations)) for c in cases])
 ROWS.append(dict(goalId=gid,wholeCurrentGoal=g,authorDecision='KEEP current complete DE/EN descriptions; new material and missing-raster AUTHOR candidates only.',profile=profile,wholeMaterialCases=cases,reason=atomic,status='needs_human_review',reviewAuthority='ai_candidate',evidenceLevel='E1',maximumClaimScope='G1',reviewId=RID,humanApproval=False,humanTrial=False,semanticAtomicityAuthorRationale=atomic,memoryAuthorDecision=dict(decision='no_memory_needed',reasonDe='Die individuelle Leistung ist begründete Anwendung auf vorliegendes Material und frische Situationen. Separate Abrufkarten würden diese Leistung nicht belegen; keine neuen Karten oder Sichtbarkeitsänderungen.',reasonEn='The individual performance is reasoned application to supplied material and fresh situations. Separate recall cards would not establish that performance; no new cards or visibility changes.')))
row('0e1065b9','concept',[
 ('Lebenskompetenzen ermöglichen mehrere Wege zur Bewältigung statt Zufriedenheit an eine einzige Belohnung zu binden.','Life skills enable several ways to cope rather than tying well-being to one reward.','Ordnet Problemlösen, Stressbewältigung und Beziehungen konkreten Situationen zu.','Links problem-solving, stress management and relationships to concrete situations.'),
 ('Schutzfaktoren verringern Risiken, garantieren aber keine Suchtfreiheit.','Protective factors reduce risks but do not guarantee freedom from addiction.','Begründet Wirkungen und Grenzen eines alltagstauglichen Plans.','Explains effects and limits of a feasible everyday plan.'),
 ('Ein eigener Entwicklungsplan kann anhand fiktiver Situationen erarbeitet werden, ohne intime Selbstauskunft.','A personal development plan can use fictional situations without intimate self-disclosure.','Passt eine Strategie an einen neuen Stressor an und benennt eine Unterstützung.','Adapts a strategy to a new stressor and names support.')], [('Zeitdruck gegenüber Gruppendruck.','Time pressure versus peer pressure.'),('Selbstorganisation gegenüber Beziehungs- und Hilfekompetenz.','Self-organisation versus relationship and help-seeking skills.')],[
 case('life-skills-c1',('Zeitdruck bewältigen','Coping with time pressure'),'Fiktiver Alex hat zwei Abgaben am selben Tag. Plan A: jede freie Minute spielen, um Stress nicht zu spüren. Plan B: Aufgaben aufteilen, eine realistische Pause einplanen und eine vertraute Person um Hilfe bitten. Die Materialkarte sagt: kurzfristige Ablenkung kann angenehm sein; wird sie der einzige Umgang mit Belastung, können Aufgaben und Beziehungen darunter leiden. Mehrere Bewältigungswege sind ein Schutzfaktor, keine Garantie.','Fictional Alex has two assignments due on one day. Plan A: play every free minute to avoid feeling stress. Plan B: divide tasks, schedule a realistic break and ask a trusted person for help. The information card says: short-term distraction can be pleasant; if it becomes the only way to cope, tasks and relationships may suffer. Several coping strategies are a protective factor, not a guarantee.','Erkläre drei Lebenskompetenzen aus Plan B, vergleiche die kurzfristigen und längerfristigen Folgen und formuliere einen umsetzbaren Entwicklungsplan.','Explain three life skills in plan B, compare short- and longer-term consequences and formulate a feasible development plan.','Problemlösen gliedert die Abgaben in Schritte; Stressbewältigung verbindet Pausen mit der Rückkehr zur Aufgabe; Beziehungsfähigkeit ermöglicht Unterstützung. A kann kurz entlasten, verschiebt aber die Aufgaben und kann den Stress verstärken. Alex könnte heute zwei kleine Arbeitsblöcke, eine Pause und eine konkrete Bitte um Hilfe planen und morgen prüfen, was funktioniert hat. Das stärkt Handlungsmöglichkeiten, beweist jedoch weder Gesundheit noch sichere Suchtvermeidung.','Problem-solving divides assignments into steps; stress management combines breaks with returning to the task; relationship skills enable support. A may give short-term relief but postpones tasks and may increase stress. Alex could plan two small work blocks, a break and one specific request for help today, then review what worked tomorrow. This strengthens options but proves neither health nor certain addiction prevention.','Neu: Alex kann die Abgabefrist nicht ändern und niemand kann die Aufgaben übernehmen. Passe den Plan an.','New: Alex cannot change the deadline and nobody can take over the work. Adapt the plan.','Priorisieren und kleine erreichbare Schritte bleiben möglich. Unterstützung kann Zuhören oder gemeinsames Sortieren bedeuten, nicht Aufgabenübernahme. Pausen und eine frühzeitige sachliche Nachricht zur Belastung bleiben sinnvoll.','Prioritising and small achievable steps remain possible. Support may mean listening or jointly organising tasks, not doing the work. Breaks and an early factual message about the workload remain useful.',[('Drei passende Kompetenzen mit konkreten Wirkungen.','Three relevant skills with concrete effects.'),('Vergleich und umsetzbarer Plan statt Garantie.','Comparison and feasible plan without a guarantee.'),('Neue Bedingungen sachlich berücksichtigt.','New conditions addressed accurately.')]),
 case('life-skills-c2',('Gruppendruck und Zufriedenheit','Peer pressure and well-being'),'Fiktive Samira wird von einer Gruppe verspottet, weil sie bei einer riskanten Mutprobe nicht mitmacht. Sie mag Musik und Bewegung, möchte aber dazugehören. Handlungsoptionen: aus Angst mitmachen; eine Grenze ruhig nennen und eine andere gemeinsame Aktivität anbieten; bei fortgesetztem Druck die Situation verlassen und Unterstützung suchen. Eine Materialkarte nennt Selbstwahrnehmung, Beziehungsfähigkeit und Problemlösen als Lebenskompetenzen.','Fictional Samira is mocked by a group for declining a risky dare. She enjoys music and exercise but wants to belong. Options: join out of fear; calmly state a boundary and offer another shared activity; leave and seek support if pressure continues. A card lists self-awareness, relationship skills and problem-solving as life skills.','Leite zwei begründete Strategien ab, die Zugehörigkeit und Selbstschutz berücksichtigen. Erkläre, warum Zufriedenheit nicht nur von der Anerkennung dieser Gruppe abhängen sollte.','Derive two reasoned strategies considering belonging and self-protection. Explain why well-being should not depend only on this group’s approval.','Samira kann ihr Unbehagen ernst nehmen und ihre Grenze benennen. Eine andere Aktivität eröffnet Beziehung ohne riskante Anpassung; bei anhaltendem Druck schützt Verlassen mit Hilfe. Kontakte, Musik und Bewegung bieten mehrere Quellen von Zufriedenheit. Das macht sie nicht unangreifbar und garantiert keine Suchtfreiheit; verantwortlich für den Druck sind die Drängenden.','Samira can take discomfort seriously and state a boundary. An alternative activity allows connection without risky conformity; leaving and seeking help offers protection if pressure persists. Relationships, music and exercise provide several sources of well-being. This does not make her invulnerable or guarantee freedom from addiction; those applying pressure are responsible for it.','Übertrage auf ein Online-Team, das dauernde Erreichbarkeit verlangt.','Transfer to an online team demanding constant availability.','Erreichbarkeitszeiten und Pausen vereinbaren, eine Grenze klar kommunizieren und bei Missachtung eine unterstützende Person oder anderes Team suchen. Die Strategie betrifft Selbstorganisation und Beziehungen, keine Diagnose von Medienabhängigkeit.','Agree on availability and breaks, communicate a boundary clearly, and seek a supportive person or another team if it is ignored. This concerns self-organisation and relationships, not diagnosing media addiction.',[('Kompetenzen mit Handlungsoptionen verknüpft.','Links skills to actions.'),('Zufriedenheit und Grenzen ohne Opferbeschuldigung erklärt.','Explains well-being and limits without blaming the target.'),('Online-Transfer ohne Ferndiagnose.','Online transfer without remote diagnosis.')])], 'Ein zusammenhängender Prozess: Lebenskompetenzen erklären und daraus einen begründeten Bewältigungs-/Entwicklungsplan ableiten. Keine voneinander unabhängigen Faktenziele oder verpflichtende persönliche Offenlegung.')
row('17dc9671','concept',[
 ('Vor und während der Schwangerschaft können äußere Einflüsse Entwicklungsrisiken verändern.','Before and during pregnancy, external influences can change developmental risks.','Unterscheidet Risikoveränderung, Wahrscheinlichkeit und sichere Einzelfallvorhersage.','Distinguishes risk changes, probability and certain individual prediction.'),
 ('Vorsorge und verlässliche Beratung ermöglichen begründete Verhaltensentscheidungen.','Preventive care and reliable advice support reasoned behavioural decisions.','Bewertet konkrete Optionen mit fachlicher Begründung statt Schuldzuweisung.','Evaluates concrete options using science rather than blame.'),
 ('Arzneimittelentscheidungen erfordern individuelle fachliche Beratung.','Medication decisions require individual professional advice.','Verwirft selbständiges Absetzen und überträgt Beratung auf eine neue Situation.','Rejects unsupervised discontinuation and transfers advice to a new situation.')], [('Vor einer möglichen Schwangerschaft gegenüber laufender Schwangerschaft.','Before a possible pregnancy versus during pregnancy.'),('Substanzexposition gegenüber Vorsorge und Unterstützung.','Substance exposure versus preventive care and support.')],[
 case('pregnancy-behaviour-c1',('Risiken ohne Vorhersagegarantie','Risks without guaranteed prediction'),'Fiktive Informationskarten: Alkohol kann die vorgeburtliche Entwicklung schädigen; eine sichere Alkoholmenge oder sichere Phase in der Schwangerschaft ist nicht bekannt. Tabakrauch birgt Risiken auch durch die Umgebung. Die Plazenta ermöglicht Stoffaustausch und ist keine undurchlässige Schutzwand. Aus einer einzelnen früheren Exposition lässt sich das spätere Ergebnis eines Kindes nicht sicher vorhersagen. Optionen einer fiktiven Schwangeren: nichts mehr klären, weil es zu spät sei; künftig Alkohol meiden, Rauch meiden und Vorsorge bzw. vertrauliche Beratung nutzen.','Fictional information cards: alcohol can harm prenatal development; no safe alcohol amount or safe phase during pregnancy is known. Tobacco smoke also poses risks through the surroundings. The placenta enables substance exchange and is not an impermeable wall. A single previous exposure does not allow certain prediction of a child’s outcome. A fictional pregnant person’s options: seek no further clarification because it is supposedly too late; avoid alcohol and smoke from now on and use prenatal care or confidential advice.','Bewerte beide Optionen, erkläre die Plazentagrenze und formuliere eine unterstützende, nicht beschuldigende Empfehlung.','Evaluate both options, explain the placenta’s limits and formulate a supportive recommendation without blame.','Die erste Option ist unbegründet: vergangene Exposition ist keine sichere Schadensdiagnose und spätere Risikovermeidung bleibt sinnvoll. Die zweite verringert vermeidbare Risiken und ermöglicht individuelle Einschätzung. Manche Stoffe gelangen über die Plazenta zum Kind; sie filtert nicht alles. Eine passende Nachricht lautet: Du musst das nicht allein klären; Vorsorge oder Beratung kann die Situation besprechen und weitere Schritte begleiten. Unterstützung durch andere beim rauchfreien Umfeld zählt ebenfalls.','The first option is unjustified: past exposure is not a certain diagnosis of harm, and later risk reduction remains useful. The second reduces avoidable risks and enables individual assessment. Some substances cross the placenta; it does not filter everything. A suitable message is: You do not have to work this out alone; care or counselling can discuss the situation and support next steps. Others helping maintain a smoke-free environment also matters.','Neu: Eine Person plant erst eine Schwangerschaft und sagt, Vorsorge könne deshalb warten.','New: a person is only planning a pregnancy and says preventive care can therefore wait.','Gesundheitsfragen, Substanzkonsum und notwendige Medikamente können schon vor einer Schwangerschaft fachlich besprochen werden. Vorbereitung schafft Handlungsmöglichkeiten; sie garantiert kein bestimmtes Schwangerschaftsergebnis.','Health questions, substance use and necessary medication can be discussed professionally before pregnancy. Preparation creates options; it does not guarantee a particular outcome.',[('Risiken und Plazentafunktion korrekt.','Correct risks and placental function.'),('Begründete Bewertung ohne Fatalismus oder Schuld.','Reasoned evaluation without fatalism or blame.'),('Vorbereitungsphase korrekt übertragen.','Correct transfer to preparation.')]),
 case('pregnancy-behaviour-c2',('Arzneimittel und Beratung','Medication and advice'),'Fiktive Lea nimmt ein ärztlich verordnetes Medikament wegen einer chronischen Erkrankung. Nach positivem Schwangerschaftstest liest sie einen ungesicherten Beitrag: Alle Medikamente sofort absetzen. Die Materialkarte sagt: Risiken unterscheiden sich nach Wirkstoff, Dosierung, Erkrankung und Zeitpunkt; auch eine unbehandelte Erkrankung kann Risiken haben. Änderungen sollen zeitnah mit der behandelnden Fachperson geklärt werden. Ernährung, Vorsorge und Unterstützung sind weitere Gesundheitsfaktoren.','Fictional Lea takes prescribed medication for a chronic condition. After a positive pregnancy test, she reads an unsupported post: stop all medication immediately. The card says risks differ by substance, dosage, condition and timing; an untreated condition may also carry risks. Changes should be discussed promptly with the treating professional. Diet, prenatal care and support are additional health factors.','Bewerte die pauschale Aussage, entwerfe einen sicheren Informationsweg und begründe zwei unterstützende Verhaltensweisen ohne Dosierungsanweisung.','Evaluate the blanket claim, design a safe information route and justify two supportive behaviours without dosage instructions.','Pauschales Absetzen ist nicht begründet. Lea sollte ihre Schwangerschaft und das konkrete Medikament zeitnah mit der behandelnden Fachperson besprechen; die Aufgabe legt weder Dosis noch Absetzen fest. Verlässliche Information berücksichtigt Erkrankung und Zeitpunkt. Regelmäßige Vorsorge und ein unterstützendes Umfeld erleichtern individuelle Gesundheitsentscheidungen; ausgewogene Ernährung ist ein weiterer Faktor, kein Ersatz für Behandlung.','Blanket discontinuation is not justified. Lea should promptly discuss the pregnancy and specific medication with her treating professional; the task determines neither dosage nor stopping treatment. Reliable information considers the condition and timing. Regular care and a supportive environment facilitate individual decisions; balanced nutrition is another factor, not a substitute for treatment.','Neue Situation: Ein Nahrungsergänzungsmittel wird als vollkommen risikofrei beworben, weil es natürlich sei.','New situation: a supplement is advertised as completely risk-free because it is natural.','Natürlich bedeutet nicht automatisch sicher. Zusammensetzung, Bedarf und mögliche Wechselwirkungen gehören in verlässliche fachliche Beratung; die Werbeaussage allein trägt keine Entscheidung.','Natural does not automatically mean safe. Ingredients, need and possible interactions belong in reliable professional advice; the advertisement alone cannot justify a decision.',[('Individuelle Risikoabwägung statt pauschalem Absetzen.','Individual risk assessment rather than blanket discontinuation.'),('Konkreter Beratungsweg und begründete Unterstützung.','Concrete advice route and reasoned support.'),('Natürlichkeitsargument fachlich geprüft.','Scientifically checks the naturalness claim.')])], 'Eine Bewertungsleistung verbindet vor- und währendgeburtliche Verhaltensoptionen mit möglichen Kindesfolgen; fachliche Beratung ist eine Grenze, kein neues Diagnoseziel.')
row('3c0f5267','concept',[
 ('Pubertät umfasst körperliche, psychische und soziale Veränderungen mit individueller Variation.','Puberty involves physical, psychological and social changes with individual variation.','Erklärt Veränderungen als Entwicklungsprozess ohne starre Normalitätsrangfolge.','Explains changes as development without a rigid ranking of normality.'),
 ('Medienbilder können bearbeitet und selektiert sein; sie bestimmen keine biologische Norm.','Media images may be edited and selected; they do not determine a biological norm.','Trennt eine beobachtete Darstellung von einer behaupteten Entwicklungsnorm.','Separates an observed portrayal from an alleged developmental norm.'),
 ('Kritische Einordnung nutzt biologische Information und die Absicht einer Darstellung.','Critical interpretation uses biological information and the portrayal’s purpose.','Begründet ein respektvolles Urteil im veränderten Medienkontext.','Justifies a respectful judgement in a changed media context.')], [('Unterschiedliches Entwicklungstempo und psychische Reaktionen.','Different developmental pace and psychological responses.'),('Bearbeitetes Bild gegenüber werbender allgemeiner Behauptung.','Edited image versus a general advertising claim.')],[
 case('puberty-development-c1',('Eine Bildnorm ist keine Entwicklungsnorm','An image norm is not a developmental norm'),'Fiktive Kim und Robin sind gleich alt, wachsen jedoch unterschiedlich schnell. Kim berichtet von stärkerem Interesse an Privatsphäre, Robin von wechselnden Gefühlen. Eine Materialkarte nennt hormonelle Veränderungen, körperliches Wachstum und soziale Erfahrungen als miteinander verbundene Faktoren; Zeitpunkt und Ausprägung unterscheiden sich. Ein Werbebild ist laut eingeblendeter Bearbeitungsliste geglättet und in Proportionen verändert. Der Werbetext behauptet: So muss jede Person in deinem Alter aussehen.','Fictional Kim and Robin are the same age but grow at different rates. Kim reports greater interest in privacy; Robin reports changing feelings. A card identifies hormonal changes, physical growth and social experiences as interacting factors; timing and expression vary. According to its editing list, an advertisement’s image was smoothed and its proportions altered. The copy claims: everyone your age must look like this.','Ordne die Veränderungen biologisch und psychosozial ein und prüfe die Werbeaussage anhand von zwei Materialangaben.','Interpret the changes biologically and psychosocially and test the advertising claim using two facts from the material.','Unterschiedliche Wachstumsgeschwindigkeit ist mit individueller Entwicklung vereinbar, kein Rang des Erwachsenseins. Gefühle und Privatsphäre verändern sich im Zusammenspiel von Körper und sozialen Erfahrungen; nicht jede Reaktion folgt allein Hormonen. Das Bild wurde bearbeitet und ist für Werbung ausgewählt. Es kann daher weder ein vorgeschriebenes Aussehen noch ein einheitliches Entwicklungstempo belegen. Respektvolle Einordnung vermeidet die Bewertung von Körpern.','Different growth rates are compatible with individual development, not a ranking of adulthood. Feelings and privacy change through interactions between the body and social experience; not every response follows hormones alone. The image was edited and selected for advertising. It therefore cannot establish a required appearance or uniform developmental pace. Respectful interpretation avoids ranking bodies.','Ein neues Video hat keinen Filterhinweis, zeigt aber nur eine ausgewählte Person. Ist seine Normbehauptung nun belegt?','A new video has no filter notice but shows only one selected person. Is its norm claim now established?','Nein. Unbekannte Bearbeitung ist keine sichere Echtheitsprüfung; auch ein unbearbeitetes Einzelfallbild belegt keine allgemeine biologische Norm. Vielfalt und die Auswahlabsicht bleiben relevant.','No. Unknown editing is not verification of authenticity; even an unedited individual image cannot establish a general biological norm. Variation and selection purpose remain relevant.',[('Entwicklungsprozess mit individueller und psychischer Variation.','Developmental process with individual and psychological variation.'),('Zwei konkrete Einwände gegen die Bildnorm.','Two concrete objections to the image norm.'),('Einzelfallgrenze übertragen.','Transfers the single-case limit.')]),
 case('puberty-development-c2',('Rollenbilder prüfen','Checking role images'),'Fiktiver Medienbeitrag: Alle Jungen müssen Gefühle verstecken, alle Mädchen müssen immer attraktiv wirken. Eine danebenstehende Biologiekarte sagt: Pubertät bringt bei vielen Menschen hormonell beeinflusste Veränderungen; ihre Ausprägung und das Erleben sind individuell. Geschlechtsidentität, Orientierung und persönliche Interessen lassen sich nicht aus Körpergröße oder einem äußeren Merkmal ablesen. Jugendliche dürfen Unterstützung suchen und ihr eigenes Tempo haben.','Fictional media post: all boys must hide feelings and all girls must always appear attractive. A biology card says puberty brings hormonally influenced changes in many people; expression and experience are individual. Gender identity, orientation and personal interests cannot be read from height or one external characteristic. Young people may seek support and develop at their own pace.','Trenne biologische Aussage und soziale Rollenerwartung, begründe ein Urteil und schreibe eine sachliche Antwort ohne intime Selbstauskunft.','Separate a biological statement from a social role expectation, justify a judgement and write a factual response without intimate disclosure.','Hormone und Entwicklung sind biologische Zusammenhänge; ein Verbot von Gefühlen oder eine Pflicht zu Attraktivität sind soziale Forderungen. Sie folgen nicht aus der Biologiekarte und missachten individuelle Vielfalt. Eine Antwort könnte lauten: Körper und Gefühle verändern sich unterschiedlich; Gefühle zu zeigen und Unterstützung zu suchen ist kein Beleg für falsche Entwicklung. Niemand muss einem Werbeideal entsprechen.','Hormones and development are biological relationships; banning feelings or requiring attractiveness are social demands. They do not follow from the biology card and disregard individual variation. A response could be: bodies and feelings change differently; showing feelings and seeking support do not show incorrect development. Nobody must match an advertising ideal.','Neu: Der Beitrag verspricht, ein bestimmtes Produkt lasse alle schneller erwachsen werden.','New: the post promises a product will make everyone mature faster.','Eine pauschale Beschleunigung ist durch die Materialangaben nicht belegt. Werbung, individuelle Entwicklung und gesundheitliche Fragen unterscheiden; bei Sorge verlässliche Beratung statt Produktversprechen nutzen.','The material does not establish universal acceleration. Distinguish advertising, individual development and health questions; use reliable advice for concerns rather than a product promise.',[('Biologie von normativer Rolle getrennt.','Separates biology from normative roles.'),('Respektvolle materialbezogene Antwort.','Respectful material-based response.'),('Werbeversprechen begründet geprüft.','Checks the advertising promise with reasons.')])], 'Entwicklung einordnen und daraus die mediale Normbehauptung beurteilen bildet eine gemeinsame Interpretationsleistung; keine Aufspaltung nach Gefühl, Hormon oder Bildtyp nötig.')
row('63856e48','concept',[
 ('STI können ohne sichtbare Beschwerden über konkrete Kontaktwege übertragen werden.','STIs can be transmitted through specific contact routes without visible symptoms.','Ordnet Krankheit, Übertragungsweg und das Fehlen eines Symptombeweises zu.','Links infection, transmission route and the absence of symptom-based certainty.'),
 ('Schutz muss zum Erreger und Weg passen; kein einzelnes Mittel schützt vollständig vor allen STI.','Protection must match the pathogen and route; no single measure fully protects against all STIs.','Vergleicht Barrieren, bestimmte Impfungen, Beratung und Tests begründet.','Compares barriers, specific vaccines, advice and tests with reasons.'),
 ('Selbst- und Fremdschutz brauchen respektvolle informierte Entscheidungen.','Self-protection and protecting others require respectful informed decisions.','Entwirft einen passenden Schutzplan und benennt Grenzen in einem neuen Fall.','Designs a relevant protection plan and states limits in a new case.')], [('HIV/Chlamydien gegenüber HPV/Hepatitis B.','HIV/chlamydia versus HPV/hepatitis B.'),('Flüssigkeits- und Schleimhautkontakt gegenüber Hautkontakt.','Fluid and mucosal contact versus skin contact.')],[
 case('sti-protection-c1',('Unsichtbar bedeutet nicht ausgeschlossen','Not visible does not mean excluded'),'Fiktive Infokarten: Chlamydien können bei sexuellen Schleimhautkontakten übertragen werden und ohne Beschwerden bestehen. HIV kann unter anderem über bestimmte sexuelle Kontakte mit infektiösen Körperflüssigkeiten übertragen werden, nicht durch gewöhnliches Zusammensitzen. Kondome senken bei korrektem Gebrauch viele sexuelle Übertragungsrisiken, sind keine Garantie. Die Pille reguliert Empfängnis und ist keine STI-Barriere. Ein fiktiver Ratgeber sagt: Wenn beide gesund aussehen, reicht die Pille gegen alle Infektionen.','Fictional cards: chlamydia can spread through sexual mucosal contact and may cause no symptoms. HIV can spread, among other routes, through certain sexual contacts involving infectious bodily fluids, not ordinary sitting together. Condoms used correctly reduce many sexual transmission risks but do not guarantee protection. The pill regulates conception and is not an STI barrier. A fictional guide claims: if both look healthy, the pill is enough against all infections.','Widerlege den Ratgeber anhand von drei Angaben und entwerfe einen sachlichen Schutzweg für eine fiktive Person.','Refute the guide using three facts and design a factual protection route for a fictional person.','Aussehen schließt symptomlose Infektionen nicht aus. Die Pille blockiert keine Übertragung; Kondome senken passende Risiken, schützen aber nicht vollständig vor jeder STI. Beratung, passend eingesetzte Barrieren und fachlich geklärte Tests können zur informierten Entscheidung gehören. HIV darf nicht als durch normales Zusammensitzen übertragbar dargestellt werden. Über Infektionsfragen respektvoll sprechen, niemanden wegen Aussehen oder vermuteter Infektion stigmatisieren.','Appearance does not exclude asymptomatic infection. The pill does not block transmission; condoms reduce relevant risks but do not fully protect against every STI. Advice, appropriately used barriers and professionally considered tests can support informed decisions. HIV must not be portrayed as spread by ordinary sitting together. Discuss infection questions respectfully and do not stigmatise anyone because of appearance or suspected infection.','Neue Behauptung: Ein einmal negativer Test garantiert unbegrenzt Sicherheit.','New claim: one negative test guarantees safety indefinitely.','Ein Test bezieht sich auf den geprüften Erreger und Zeitpunkt; Zeitpunkt nach möglicher Exposition und spätere Kontakte spielen eine Rolle. Ein negatives Ergebnis ist keine zeitlich unbegrenzte Garantie für alle STI.','A test concerns the tested pathogen and time; time after possible exposure and later contacts matter. A negative result is not an unlimited guarantee against all STIs.',[('Drei passende Fehler begründet widerlegt.','Refutes three relevant errors with reasons.'),('Passender Schutz ohne Vollgarantie oder Stigma.','Relevant protection without a full guarantee or stigma.'),('Testgrenze korrekt übertragen.','Correct transfer of test limits.')]),
 case('sti-protection-c2',('Impfung ist erregerspezifisch','Vaccination is pathogen-specific'),'Fiktive Karten: HPV kann auch über engen sexuellen Hautkontakt übertragen werden; Kondome decken nicht jede berührte Hautstelle ab. Impfungen können vor bestimmten HPV-Typen und Hepatitis B schützen. Für Chlamydien und HIV besteht keine allgemein verfügbare vorbeugende Schutzimpfung. Hygiene ersetzt bei STI weder passende Barrieren noch fachliche Beratung. Eine Werbung fasst zusammen: Eine einzige Impfung und Waschen schützen gegen jede STI.','Fictional cards: HPV can also spread through close sexual skin contact; condoms do not cover every contacting skin area. Vaccines can protect against certain HPV types and hepatitis B. There is no generally available preventive vaccine against chlamydia or HIV. For STIs, hygiene replaces neither suitable barriers nor professional advice. An advertisement concludes: one vaccination and washing protect against every STI.','Beurteile die Werbung, verknüpfe für zwei Erreger Übertragung und passende Prävention und begründe die Rolle von Beratung.','Evaluate the advertisement, link transmission and relevant prevention for two pathogens and justify the role of advice.','Die Werbung verallgemeinert unzulässig. HPV-Impfung betrifft bestimmte Typen; Barrieren reduzieren Risiken, lassen aber unbedeckte Hautkontakte zu. Für Chlamydien kann eine passende Barriere und fachlich geklärte Test-/Behandlungsfrage relevant sein, keine erfundene Schutzimpfung. Beratung klärt individuelle Fragen und konkrete Erreger statt vermeintlichem Rundumschutz. Waschen bietet keinen allgemeinen STI-Schutz.','The advertisement overgeneralises. HPV vaccination concerns certain types; barriers reduce risks but leave uncovered skin contacts possible. For chlamydia, an appropriate barrier and professionally considered testing or treatment questions may be relevant, not an invented vaccine. Advice clarifies individual questions and specific pathogens instead of supposed universal protection. Washing does not provide general STI protection.','Übertrage auf die Behauptung: Hepatitis-B-Impfung verhindert auch jede HPV-Infektion.','Transfer to the claim: hepatitis B vaccination also prevents every HPV infection.','Die Erreger sind verschieden; Hepatitis-B-Impfung schützt nicht automatisch gegen HPV. Auch eine HPV-Impfung deckt nicht jeden Typ ab. Erregerspezifische Information ist erforderlich.','The pathogens differ; hepatitis B vaccination does not automatically protect against HPV. Even HPV vaccination does not cover every type. Pathogen-specific information is required.',[('Werbeverallgemeinerung und Hautkontaktgrenze erklärt.','Explains the advertising overgeneralisation and skin-contact limit.'),('Zwei erregerspezifische Schutzbegründungen.','Two pathogen-specific prevention explanations.'),('Impftransfer ohne erfundene Kreuzgarantie.','Vaccine transfer without an invented cross-guarantee.')])], 'Ein zusammenhängender Präventionsentscheid verknüpft Erreger/Weg mit Schutz für sich und andere; Listenabruf allein genügt nicht.')
row('6add2bde','concept',[
 ('Selbstbestimmung erfordert freiwillige, konkrete und widerrufliche Zustimmung; Druck hebt Freiwilligkeit auf.','Self-determination requires voluntary, specific, revocable consent; pressure undermines voluntariness.','Prüft an einem Fall Zustimmung und Würde anhand konkreter Aussagen.','Checks consent and dignity in a case using concrete statements.'),
 ('Körper- und Rollenbilder sind keine Pflicht für Identität oder persönliches Verhalten.','Body and role images are not obligations for identity or personal behaviour.','Unterscheidet Selbstausdruck von einer medialen Normforderung.','Distinguishes self-expression from a media-imposed norm.'),
 ('Kritische Beurteilung verbindet Grenzen, Privatsphäre und faire Handlungsoptionen.','Critical assessment links boundaries, privacy and fair options.','Formuliert im neuen Kontext ein begründetes respektvolles Urteil.','Formulates a reasoned respectful judgement in a new context.')], [('Persönliches Gegenüber gegenüber medialer Veröffentlichung.','Personal interaction versus media publication.'),('Bearbeitung, Rollenerwartung und Entscheidungsdruck.','Editing, role expectations and decision pressure.')],[
 case('self-determination-c1',('Zustimmung unter Druck','Consent under pressure'),'Fiktive Erwachsene Mira und Jo sprechen über ein gemeinsames Foto. Mira stimmt zunächst einer privaten Aufnahme zu, möchte später aber keine Veröffentlichung. Jo sagt: Wer mich mag, muss damit einverstanden sein. Ein Werbeclip sagt außerdem: Eine gute Partnerin sieht immer wie das bearbeitete Model aus. Die Materialkarte unterscheidet freiwillige Zustimmung zu einem konkreten Schritt, jederzeit veränderbare Grenzen, persönliche Würde und kommerziell erzeugte Idealbilder.','Fictional adults Mira and Jo discuss a shared photo. Mira initially agrees to a private picture but later does not want publication. Jo says: anyone who likes me must agree. An advertisement also says a good partner always looks like the edited model. The card distinguishes voluntary consent to a specific action, changeable boundaries, personal dignity and commercially created ideals.','Beurteile Jos Forderung und die Werbenorm getrennt. Begründe eine Handlungsoption, die Selbstbestimmung und Würde berücksichtigt.','Assess Jo’s demand and the advertising norm separately. Justify an option respecting self-determination and dignity.','Die Zustimmung zur Aufnahme ist keine pauschale Zustimmung zur Veröffentlichung. Miras neue Grenze ist zu respektieren; der Liebesbeweis übt Druck aus. Das bearbeitete Werbemodel setzt keine Pflicht für Aussehen oder Rollenverhalten. Jo sollte nicht veröffentlichen, die Grenze akzeptieren und ohne Druck nachfragen, was Mira möchte. Unterschiedliche Körper und Rollen sind kein Mangel an Würde.','Consent to taking a picture is not blanket consent to publication. Mira’s new boundary must be respected; the proof-of-love demand applies pressure. An edited advertising model creates no obligation concerning appearance or roles. Jo should not publish, accept the boundary and ask without pressure what Mira wants. Different bodies and roles are no deficiency in dignity.','Neu: Jo sagt, ein früherer privater Kuss erlaube automatisch jede weitere Nähe.','New: Jo says a previous private kiss automatically permits all further intimacy.','Zustimmung ist konkret und widerruflich; frühere Nähe erteilt keine allgemeine Erlaubnis. Wünsche und Grenzen ohne Druck klären und Ablehnung respektieren.','Consent is specific and revocable; earlier intimacy does not grant universal permission. Clarify wishes and boundaries without pressure and respect refusal.',[('Konkrete Zustimmung und Druck korrekt beurteilt.','Correctly judges specific consent and pressure.'),('Medienideal von Würde und Selbstbestimmung getrennt.','Separates media ideals from dignity and self-determination.'),('Neue Grenze konsistent übertragen.','Consistently transfers to a new boundary.')]),
 case('self-determination-c2',('Ein Rollenbild hinterfragen','Questioning a role image'),'Fiktive Kampagne zeigt ausschließlich muskulöse Männer und stark bearbeitete Frauenporträts. Ihre Botschaft lautet: Nur diese Körper und Rollen sind begehrenswert. Eine kommentierende Person will das selbstbestimmte Foto einer anderen Person ohne Zustimmung verändern und öffentlich bewerten. Die Materialkarte sagt: Medienauswahl und Bildbearbeitung sind gestaltete Darstellungen; persönliche Würde und freie Entfaltung hängen nicht von diesen Vorgaben ab.','A fictional campaign shows only muscular men and heavily edited women’s portraits. Its message is: only these bodies and roles are desirable. A commenter wants to alter another person’s self-chosen photo and publicly judge it without permission. The card says media selection and editing are constructed portrayals; personal dignity and free development do not depend on them.','Bewerte die Normforderung und die geplante Bildänderung. Erkläre, warum Kritik an einem Medienideal nicht zur Abwertung echter Körper führen darf.','Assess the norm claim and planned alteration. Explain why criticising a media ideal must not become devaluation of real bodies.','Die Kampagne wählt eng aus und behauptet eine allgemeine Werteskala ohne Grundlage. Eine fremdbestimmte Bildänderung und öffentliche Körperbewertung missachten Privatsphäre und freie Entfaltung. Kritik sollte die Auswahl, Bearbeitung und normierende Botschaft betreffen, nicht Menschen mit einem bestimmten Körper. Eine respektvolle Antwort fordert Zustimmung und vielfältige selbstbestimmte Darstellung.','The campaign selects narrowly and asserts an unsupported universal value scale. Imposed editing and public body judgement disregard privacy and free development. Criticism should target selection, editing and the norm-setting message, not people with a certain body. A respectful response calls for consent and diverse self-chosen portrayal.','Übertrage auf eine Werbung, die einen Beruf nur einem Geschlecht zuschreibt.','Transfer to an advertisement assigning a profession to only one gender.','Die Zuschreibung ist ein Rollenbild, keine biologische Grenze persönlicher Möglichkeiten. Die Darstellung und ihre Auswahlabsicht kritisieren und individuelle Interessen respektieren.','The assignment is a role image, not a biological boundary of personal possibilities. Criticise the portrayal and its selection purpose while respecting individual interests.',[('Normforderung und Autonomieproblem getrennt begründet.','Separately explains the norm claim and autonomy issue.'),('Kritik richtet sich auf Darstellung statt Körperabwertung.','Criticism targets portrayal rather than body devaluation.'),('Rollenbildtransfer begründet.','Reasoned transfer to role images.')])], 'Eine gemeinsame ethisch-fachliche Urteilsleistung: Selbstbestimmung/Würde dienen als Kriterien sowohl für konkrete Handlungen als auch mediale Normforderungen.')
row('6de6ad3b','concept',[
 ('Gesundheitsfolgen betreffen eigenes und fremdes Verhalten und sind nicht identisch mit bloßem Wohlgefühl.','Health consequences involve one’s own and others’ behaviour and are not identical to immediate comfort.','Unterscheidet kurzfristigen Nutzen und mögliche längerfristige Folgen.','Distinguishes short-term benefit from possible longer-term consequences.'),
 ('Entscheidungen nutzen fachliche Kriterien und berücksichtigen andere Menschen.','Decisions use scientific criteria and consider other people.','Wägt mindestens zwei Optionen mit Gesundheits- und Alltagskriterien ab.','Weighs at least two options using health and everyday criteria.'),
 ('Eine begründete Entscheidung bleibt bei veränderter Lage überprüfbar.','A reasoned decision remains open to review when circumstances change.','Passt einen praktikablen Plan ohne Garantie oder Ferndiagnose an.','Adapts a feasible plan without guarantees or remote diagnosis.')], [('Lärm und Rücksicht gegenüber Schlaf, Zeit und Erholung.','Noise and consideration versus sleep, time and recovery.'),('Eigene Möglichkeiten gegenüber Folgen für Dritte.','Personal options versus consequences for others.')],[
 case('health-decisions-c1',('Lautes Fest, gemeinsame Verantwortung','A loud event and shared responsibility'),'Fiktive Schulgruppe plant ein Konzert. Option A: dicht vor dem Lautsprecher stehen, damit alle die Musik besonders intensiv erleben. Option B: Abstand, geeigneter Gehörschutz und Ruhepausen anbieten. Eine Karte erklärt: hohe Schallbelastung kann das Gehör schädigen; Risiko hängt unter anderem von Pegel und Dauer ab. Manche Personen empfinden Lärm früher als belastend. Die Gruppe möchte gemeinsam teilnehmen und darf niemanden zu riskanter Belastung drängen.','A fictional school group plans a concert. Option A: stand close to the speaker so everyone experiences the music intensely. Option B: offer distance, suitable hearing protection and quiet breaks. A card explains that high sound exposure may damage hearing; risk depends partly on level and duration. Some people find noise stressful sooner. The group wants shared participation and must not pressure anyone into risky exposure.','Wäge beide Optionen mit drei Kriterien ab und begründe eine Entscheidung für eigene und fremde Gesundheit.','Weigh both options using three criteria and justify a decision concerning personal and others’ health.','Intensives Erlebnis ist ein kurzfristiger Nutzen, kein Beleg für gesundheitliche Sicherheit. Gehörschutz, geringere Belastungsdauer und Abstand sprechen für B; gemeinsame Teilnahme kann durch einen vereinbarten Treffpunkt erhalten bleiben. Unterschiedliche Belastung und freiwillige Pausen berücksichtigen die anderen. Die Entscheidung reduziert Risiken, garantiert aber keine Unbedenklichkeit und ersetzt keine Beachtung tatsächlicher Lautstärke.','An intense experience is a short-term benefit, not evidence of health safety. Hearing protection, shorter exposure and distance favour B; a meeting point can preserve shared participation. Considering different tolerance and voluntary breaks respects others. The decision reduces risk but does not guarantee safety or replace attention to actual sound levels.','Neu: Eine Person kann den bereitgestellten Gehörschutz nicht benutzen.','New: one person cannot use the supplied hearing protection.','Nicht einfach bei gleichem Risiko weitermachen oder ausschließen. Größeren Abstand, geringere Lautstärke, kürzere Teilnahme oder ruhigere gemeinsame Alternative prüfen; ihre Bedürfnisse respektvoll besprechen.','Do not simply continue at the same risk or exclude the person. Consider greater distance, lower volume, shorter attendance or a quieter shared alternative; discuss their needs respectfully.',[('Gesundheitsfolge mit Pegel/Dauer und Nutzen unterschieden.','Distinguishes health effects from enjoyment using level and duration.'),('Drei Kriterien, Entscheidung und Rücksicht begründet.','Explains three criteria, a decision and consideration for others.'),('Veränderte Einschränkung sinnvoll berücksichtigt.','Meaningfully addresses the changed constraint.')]),
 case('health-decisions-c2',('Planen unter Belastung','Planning under workload'),'Fiktive Robin arbeitet an einer Abgabe. Plan A lässt mehrere Nächte fast ohne Schlaf, regelmäßige Mahlzeiten und Pausen verstreichen. Plan B priorisiert notwendige Schritte, reserviert Schlaf und kurze Erholung und bittet um Hilfe beim Sortieren. Die Materialkarte sagt: Schlaf unterstützt Erholung und Lernen; regelmäßige Ernährung und Bewegung tragen zum Wohlbefinden bei. Einzelne Gewohnheiten erklären nicht jede Erkrankung. Robin betreut außerdem ein Familienmitglied und hat begrenzte Zeit.','Fictional Robin works on an assignment. Plan A allows several nights with almost no sleep, regular meals or breaks. Plan B prioritises necessary steps, reserves sleep and brief recovery, and asks for help organising tasks. A card says sleep supports recovery and learning; regular nutrition and movement contribute to well-being. Individual habits do not explain every illness. Robin also cares for a family member and has limited time.','Wäge die Pläne mit Gesundheits-, Zeit- und Rücksichtskriterien ab und entwirf eine realistische Entscheidung ohne Robin für Belastung verantwortlich zu machen.','Weigh the plans using health, time and consideration criteria and design a realistic decision without blaming Robin for the workload.','A gewinnt scheinbar Arbeitszeit, kann aber Erholung und Konzentration beeinträchtigen. B ist gesundheitlich begründeter, muss jedoch zur verfügbaren Zeit passen: wichtige Aufgaben priorisieren, kurze Pausen planen, Betreuung mit Unterstützenden abstimmen und notwendige Grenzen kommunizieren. Belastung hat auch soziale Ursachen; nicht jede Erkrankung lässt sich durch Willenskraft verhindern.','A seemingly gains work time but may impair recovery and concentration. B has a better health rationale but must fit available time: prioritise important tasks, plan brief breaks, coordinate care with supporters and communicate necessary boundaries. Workload also has social causes; willpower cannot prevent every illness.','Übertrage auf eine Woche mit unvorhersehbarer Schichtzeit statt schulischer Abgabe.','Transfer to a week of unpredictable shift times rather than an assignment.','Erholungszeiten und Mahlzeiten soweit möglich flexibel planen, Änderungen früh abstimmen und externe Unterstützung suchen. Ein starres Ideal ist unrealistisch; Gesundheitskriterien bleiben relevant.','Plan recovery and meals flexibly where possible, coordinate changes early and seek external support. A rigid ideal is unrealistic; health criteria remain relevant.',[('Kurz- und längerfristige Folgen begründet.','Explains short- and longer-term consequences.'),('Praktikable Entscheidung mit sozialer Rücksicht.','Feasible decision with social consideration.'),('Flexibler Transfer ohne Gesundheitsgarantie.','Flexible transfer without a health guarantee.')])], 'Kriteriengeleitete gesundheitsbezogene Abwägung ist eine konkrete Prozesskompetenz. Themen wechseln, der prüfbare Entscheidungsprozess bleibt derselbe; keine pauschale Gesamtabdeckung aller Landes-Humanbiologieziele.')
row('773a297d','modeling',[
 ('Wiederholung, Belohnung und Hinweisreize können Verhalten verstärken; Suchtentstehung ist mehrfaktoriell.','Repetition, rewards and cues can reinforce behaviour; addiction develops through multiple factors.','Erklärt gerichtete Modellbeziehungen statt eines bloßen Etikettenkreises.','Explains directed model relationships rather than a circle of labels.'),
 ('Kontrollverlust und Fortsetzung trotz Schaden unterscheiden problematische Entwicklung von beliebiger Nutzung.','Loss of control and continuing despite harm distinguish problematic development from ordinary use.','Beschreibt mögliche körperliche, psychische und soziale Folgen ohne Einzelfalldiagnose.','Describes possible physical, psychological and social consequences without diagnosing an individual.'),
 ('Modelle vereinfachen und erklären keine sichere individuelle Entwicklung.','Models simplify and do not predict an individual course with certainty.','Überträgt eine Erklärung auf einen neuen Kontext und benennt Modellgrenzen.','Transfers an explanation to a new context and states model limits.')], [('Substanzbezogene gegenüber nicht substanzbezogener Wiederholung.','Substance-related versus non-substance-related repetition.'),('Kurzfristige Verstärkung gegenüber längerfristigen Folgen und Hilfe.','Short-term reinforcement versus longer-term consequences and help.')],[
 case('addiction-model-c1',('Einen Kreislauf erklären','Explaining a feedback cycle'),'Fiktives Modell: Belastung → kurzes entlastendes Spielen → Erleichterung → erhöhte Wahrscheinlichkeit erneuten Spielens bei Belastung. Wiederholte Benachrichtigungen können Hinweisreize sein. Fiktiver Fall: Eine Person spielt trotz wiederholter eigener Begrenzungsversuche weiter, schläft über Wochen schlechter und vernachlässigt Kontakte. Das Material enthält keine klinische Diagnose. Die Karte sagt: biologische, psychische und soziale Faktoren beeinflussen Entwicklung; viel Nutzung allein beweist keine Sucht.','Fictional model: stress → briefly relieving play → relief → greater likelihood of playing again when stressed. Repeated notifications can act as cues. Fictional case: a person continues despite repeated attempts to limit use, sleeps poorly for weeks and neglects relationships. The material contains no clinical diagnosis. The card says biological, psychological and social factors influence development; heavy use alone does not prove addiction.','Erkläre zwei Modellpfeile, beschreibe drei mögliche Folgen und benenne zwei Grenzen sowie eine unterstützende Handlungsoption.','Explain two model arrows, describe three possible consequences and state two limits and one supportive option.','Kurzfristige Erleichterung kann das Spielen als Reaktion auf Belastung verstärken; Hinweisreize können den erneuten Impuls auslösen. Weniger Schlaf kann körperliche Erholung betreffen, starke Bindung an Spielen psychische Belastung verstärken und Kontaktverlust soziale Folgen haben. Das Modell ist vereinfacht, enthält keine individuelle Diagnose und keine zwangsläufige Entwicklung. Gespräche ohne Beschämung und bei anhaltenden Problemen fachliche Beratung sind mögliche Unterstützung.','Short-term relief can reinforce playing as a response to stress; cues may trigger another impulse. Less sleep may affect physical recovery, strong dependence on play may increase psychological strain, and lost contact may have social consequences. The model is simplified, contains no individual diagnosis and describes no inevitable course. Non-shaming conversations and professional advice for persistent problems are possible support.','Neu: Dieselbe tägliche Nutzungszeit geht mit eingehaltenen Grenzen, erholsamem Schlaf und gepflegten Kontakten einher.','New: the same daily use time accompanies respected limits, restorative sleep and maintained relationships.','Die gleiche Dauer rechtfertigt nicht dieselbe Einordnung. Kontrollierbarkeit und Folgen unterscheiden sich; das Modell muss diese Informationen berücksichtigen und darf Zeit nicht als automatische Diagnosegrenze setzen.','The same duration does not justify the same interpretation. Controllability and consequences differ; the model must consider this information and must not turn time into an automatic diagnostic threshold.',[('Zwei gerichtete Verstärkungsbeziehungen erklärt.','Explains two directed reinforcement relationships.'),('Drei Folgen und Modell-/Diagnosegrenzen.','Three consequences and model/diagnostic limits.'),('Gleiche Dauer ohne automatische Diagnose beurteilt.','Judges equal duration without automatic diagnosis.')]),
 case('addiction-model-c2',('Biologische und soziale Faktoren','Biological and social factors'),'Fiktive Modellkarten zu Alkoholabhängigkeit nennen kurzfristige Belohnung oder Stressentlastung, wiederholtes Verhalten, mögliche Gewöhnung sowie Einflüsse von sozialer Umgebung und individueller Verwundbarkeit. Ein vereinfachter Pfeilplan zeigt: Belastung → Konsum → kurzfristige Entlastung → erneuter Konsum; soziale Konflikte können Belastung erneut steigern. Eine Person behauptet, Sucht entstehe immer aus Charakterschwäche und sei durch einen einzigen Entschluss sicher beendet.','Fictional alcohol-dependence model cards list short-term reward or stress relief, repeated behaviour, possible habituation, and influences of social surroundings and individual vulnerability. A simplified arrow diagram shows stress → use → short-term relief → repeated use; social conflict may increase stress again. Someone claims addiction always results from weak character and certainly ends after one decision.','Erkläre den Kreislauf mehrfaktoriell, beurteile die Behauptung und unterscheide mögliche Folgen von sicherem Einzelfallwissen.','Explain the cycle using several factors, assess the claim and distinguish possible consequences from certain individual knowledge.','Entlastung kann Wiederholung verstärken; Gewöhnung und soziale Konflikte können die Entwicklung verändern. Biologische, psychische und soziale Faktoren wirken zusammen, daher ist Charakterschwäche keine tragfähige Erklärung. Körperliche Schäden, psychische Belastung und Beziehungskonflikte sind mögliche Folgen, nicht aus dem Diagramm sicher diagnostiziert. Unterstützung und professionelle Behandlung können nötig sein; das Material gibt keine Anweisung zu einem eigenständigen Entzug.','Relief can reinforce repetition; habituation and social conflict can alter development. Biological, psychological and social factors interact, so weak character is not a sound explanation. Physical harm, psychological distress and relationship conflict are possible consequences, not certain diagnoses derived from the diagram. Support and professional treatment may be needed; the material gives no instruction for unsupervised withdrawal.','Neue Variation: Eine unterstützende Beziehung reduziert Stress, aber biologische Risiken bleiben bestehen.','New variation: a supportive relationship reduces stress but biological risks remain.','Der Stresspfeil kann schwächer werden, nicht alle Einflüsse verschwinden. Unterstützung kann schützen, garantiert aber keine Genesung oder Suchtfreiheit; das Modell muss mehrere Faktoren behalten.','The stress link may weaken, but not all influences disappear. Support can protect without guaranteeing recovery or absence of addiction; the model must retain several factors.',[('Mehrfaktorieller Kreislauf statt moralischem Etikett.','Multifactorial cycle rather than a moral label.'),('Folgen und Behandlungsgrenzen sauber unterschieden.','Clearly distinguishes consequences and treatment limits.'),('Veränderten Faktor ohne Alles-oder-nichts übertragen.','Transfers a changed factor without all-or-nothing reasoning.')])], 'Die Erklärung eines Entstehungs-/Folgenmodells ist eine einheitliche modellgestützte Kompetenz. Körperliche, psychische und soziale Folgen sind Perspektiven auf denselben Prozess, keine separaten Abrufziele.')
row('848334f3','representation',[
 ('Schwangerschaft verläuft über Entwicklungsphasen mit veränderter Organbildung und Wachstum.','Pregnancy proceeds through developmental phases involving organ formation and growth.' , 'Ordnet Einnistung, Embryonal- und Fetalentwicklung sowie Geburt zeitlich korrekt.','Orders implantation, embryonic and fetal development, and birth correctly.'),
 ('Plazenta und Nabelschnur ermöglichen Versorgung; Risiken sind keine sichere Ergebnisvorhersage.','The placenta and umbilical cord support exchange; risks do not predict outcomes with certainty.','Beschreibt Versorgung und mögliche Risiken ohne Blutmischungs- oder Schutzgarantie.','Describes supply and possible risks without a blood-mixing claim or protection guarantee.'),
 ('Geburt ist ein Prozess; ein Unterrichtsmodell ersetzt weder Betreuung noch individuelle Prognose.','Birth is a process; a teaching model replaces neither care nor individual prognosis.','Beschreibt Grundphasen und überträgt die Grenzen auf einen neuen Fall.','Describes basic stages and transfers the limits to a new case.')], [('Zeitfolge gegenüber Versorgungs- und Risikozusammenhang.','Sequence versus supply and risk relationships.'),('Typischer Ablauf gegenüber individueller Abweichung.','Typical course versus individual variation.')],[
 case('pregnancy-birth-c1',('Vom Einnisten zur Geburt','From implantation to birth'),'Fiktive ungeordnete Karten: A Wachstum und Reifung des Fetus; B Einnistung einer frühen Keimanlage in der Gebärmutterschleimhaut; C Geburt mit Öffnung des Muttermundes, Austritt des Kindes und nachfolgender Plazenta; D frühe Organbildung während der Embryonalentwicklung. Die Plazenta ermöglicht Austausch von Sauerstoff, Nährstoffen und Abfallstoffen zwischen getrennten mütterlichen und kindlichen Kreisläufen. Manche schädlichen Stoffe können passieren. Eine Karte nennt Alkohol und Tabakrauch als vermeidbare Risikofaktoren.','Fictional unordered cards: A fetal growth and maturation; B implantation of an early conceptus in the uterine lining; C birth involving cervical opening, birth of the child and subsequent delivery of the placenta; D early organ formation during embryonic development. The placenta enables exchange of oxygen, nutrients and waste between separate maternal and fetal circulations. Some harmful substances can pass. A card names alcohol and tobacco smoke as avoidable risk factors.','Ordne die Karten, beschreibe Verlauf und Geburt und erkläre Versorgung sowie zwei Risikogrenzen.','Order the cards, describe the course and birth, and explain supply and two risk limits.','B → D → A → C. Auf Einnistung folgen frühe Organbildung und später überwiegend Wachstum und Reifung. Bei einer typischen vaginalen Geburt öffnet sich der Muttermund, das Kind wird geboren und die Plazenta folgt; der tatsächliche Geburtsweg kann anders sein. Austausch erfolgt über die Plazenta, nicht durch eine gemeinsame Blutmischung. Alkohol und Rauch können Risiken erhöhen; die Plazenta ist kein vollständiger Filter und eine Exposition sagt den Einzelfall nicht sicher voraus.','B → D → A → C. Implantation is followed by early organ formation and later predominantly growth and maturation. In a typical vaginal birth, the cervix opens, the child is born and the placenta follows; the actual birth route may differ. Exchange occurs through the placenta, not a shared mixture of blood. Alcohol and smoke can increase risks; the placenta is not a complete filter and exposure does not certainly predict an individual outcome.','Ein neues Schaubild zeigt eine Geburt durch Kaiserschnitt. Widerlegt es die vorgeburtliche Zeitfolge?','A new diagram shows birth by caesarean section. Does it refute the prenatal sequence?','Nein. Der Geburtsweg verändert die Entbindung, nicht die grundlegende Reihenfolge Einnistung, Embryonal- und Fetalentwicklung. Medizinische Gründe und Betreuung lassen sich aus dem Schulbild nicht beurteilen.','No. The birth route changes delivery, not the basic order of implantation, embryonic and fetal development. Medical reasons and care cannot be judged from the school illustration.',[('Zeitfolge und Entwicklung korrekt.','Correct sequence and development.'),('Geburtsgrundphasen, Versorgung und Risiken ohne falsche Garantie.','Basic birth stages, supply and risks without a false guarantee.'),('Geburtsweg und Entwicklungsfolge unterschieden.','Distinguishes birth route from developmental sequence.')]),
 case('pregnancy-birth-c2',('Ein Versorgungsbild prüfen','Checking a supply diagram'),'Fiktives Plakat zeigt einen Fetus in der Gebärmutter, verbunden über Nabelschnur mit der Plazenta. Darunter steht fälschlich: Mütterliches Blut fließt direkt durch das Kind, und die Plazenta hält alle Medikamente zurück. Ein Begleittext sagt: Entwicklung verändert sich über die Schwangerschaft; Vorsorge dient unter anderem dem Beobachten des Verlaufs und dem Besprechen von Risiken. Die Zeichnung ist nicht maßstabsgetreu.','A fictional poster shows a fetus in the uterus connected by an umbilical cord to the placenta. Its incorrect caption says maternal blood flows directly through the child and the placenta blocks all medication. Accompanying text says development changes during pregnancy; prenatal care includes monitoring the course and discussing risks. The drawing is not to scale.','Korrigiere beide Aussagen, beschreibe den Zusammenhang mit dem Schwangerschaftsverlauf und benenne eine Grenze des Schaubilds.','Correct both statements, describe the connection to the course of pregnancy and name a diagram limit.','Mütterlicher und kindlicher Blutkreislauf bleiben normalerweise getrennt; Stoffe werden über die Plazenta ausgetauscht. Nicht alle Stoffe werden zurückgehalten, daher Arzneimittelfragen fachlich klären, nicht selbst absetzen. Frühe Organbildung und spätere Reifung verändern Bedürfnisse und mögliche Risiken; Vorsorge begleitet den Verlauf. Ein einzelnes unmaßstäbliches Bild gibt weder Entwicklungsalter noch Gesundheitsprognose sicher an.','Maternal and fetal circulation normally remain separate; substances exchange across the placenta. Not all substances are blocked, so medication questions require professional discussion rather than self-directed stopping. Early organ formation and later maturation change needs and possible risks; prenatal care accompanies the course. One non-scale image cannot establish developmental age or health prognosis with certainty.','Neu: Ein großes gezeichnetes Kind wird als Beweis für eine risikofreie Schwangerschaft angeführt.','New: a large drawn baby is offered as proof of a risk-free pregnancy.','Größe in einer schematischen Zeichnung ist keine Messung. Schwangerschaftsverlauf und Risiken brauchen individuelle fachliche Einschätzung; das Bild liefert keinen solchen Befund.','Size in a schematic drawing is not a measurement. Pregnancy course and risks require individual professional assessment; the image supplies no such finding.',[('Getrennte Kreisläufe und durchlässige Plazenta korrekt.','Correct separate circulations and placental permeability.'),('Verlauf und Vorsorge ohne selbständige Behandlung erklärt.','Explains course and care without self-directed treatment.'),('Maßstabs-/Prognosegrenze erkannt.','Recognises scale and prognosis limits.')])], 'Eine zeitlich-funktionale Verlaufsbeschreibung verbindet Schwangerschaft, Versorgung, Geburt und relevante Risiken; Grenzen sind Teil derselben Darstellung, keine klinische Diagnosekompetenz.')
row('91f62a7b','concept',[
 ('Körperliche Pubertätsveränderungen verlaufen individuell und nicht bei allen gleichzeitig.','Physical changes in puberty vary individually and do not occur simultaneously for everyone.','Beschreibt mehrere Veränderungen ohne Altersrangfolge oder Körperwertung.','Describes several changes without age ranking or body judgement.'),
 ('Primäre Geschlechtsmerkmale betreffen vorhandene Fortpflanzungsorgane; sekundäre Merkmale entwickeln sich typischerweise in der Pubertät.','Primary sex characteristics concern existing reproductive organs; secondary characteristics typically develop during puberty.','Ordnet Beispiele richtig ein und begründet die Unterscheidung.','Classifies examples correctly and explains the distinction.'),
 ('Ein Merkmal allein bestimmt weder Entwicklungsvollständigkeit noch Identität und Orientierung.','One characteristic alone determines neither developmental completion nor identity and orientation.','Korrigiert eine Schlussfolgerung und überträgt die Variationsgrenze.','Corrects an inference and transfers the variation limit.')], [('Merkmalsarten gegenüber Wachstum und Körperfunktion.','Types of characteristics versus growth and bodily function.'),('Unterschiedliche Reihenfolge und Ausprägung in fiktiven Fällen.','Different sequence and expression in fictional cases.')],[
 case('puberty-physical-c1',('Merkmalskarten sortieren','Sorting characteristic cards'),'Fiktive Karten: Eierstöcke und Hoden sind Fortpflanzungsorgane, die vor der Pubertät vorhanden sind; in der Pubertät verändern sich ihre Aktivität und Reifung. Häufige Veränderungen sind Wachstumsschub, stärkerer Körperhaarwuchs, veränderte Stimme, Brustentwicklung und veränderte Haut mit möglichen Pickeln. Nicht alle treten gleich stark oder gleichzeitig auf. Die Zuordnung von sekundären Merkmalen in dieser Aufgabe betrifft typischen Körperhaarwuchs, Stimmveränderung und Brustentwicklung; Wachstum und Hautänderung sind allgemeine Begleitveränderungen.','Fictional cards: ovaries and testes are reproductive organs present before puberty; their activity and maturation change during puberty. Common changes include a growth spurt, more body hair, voice changes, breast development and skin changes with possible spots. They do not all occur to the same degree or simultaneously. The secondary-characteristic classification in this task concerns typical body-hair, voice and breast changes; growth and skin changes are general accompanying changes.','Unterscheide primäre und sekundäre Geschlechtsmerkmale, ordne drei Beispiele zu und beschreibe zwei weitere körperliche Veränderungen mit einer Variationsgrenze.','Distinguish primary and secondary sex characteristics, classify three examples and describe two other physical changes with a variation limit.','Hoden und Eierstöcke sind primäre Merkmale bzw. Fortpflanzungsorgane; sie entstehen nicht erst in der Pubertät. Brustentwicklung, Stimmveränderung und typischer Körperhaarwuchs sind Beispiele sekundärer Merkmale. Wachstumsschub und veränderte Haut sind weitere körperliche Veränderungen. Zeitpunkt, Reihenfolge und Ausprägung unterscheiden sich; aus einem fehlenden sichtbaren Merkmal folgt keine sichere Entwicklungsstörung.','Testes and ovaries are primary characteristics or reproductive organs; they do not first appear in puberty. Breast development, voice change and typical body hair are examples of secondary characteristics. A growth spurt and skin changes are other physical changes. Timing, sequence and expression vary; one absent visible characteristic does not establish a developmental disorder.','Neu: Eine Person folgert aus tiefer Stimme die Orientierung und Geschlechtsidentität einer anderen.','New: someone infers another person’s orientation and gender identity from a deep voice.','Ein körperliches Merkmal erlaubt diese Schlussfolgerung nicht. Körperliche Entwicklung, Identität und Orientierung unterscheiden; Menschen nicht anhand eines Merkmals festlegen.','One physical characteristic does not permit this inference. Distinguish physical development, identity and orientation; do not define people by one characteristic.',[('Primäre/sekundäre Merkmale mit drei Zuordnungen korrekt.','Correct primary/secondary distinction with three classifications.'),('Zwei weitere Veränderungen und individuelle Variation erklärt.','Explains two other changes and individual variation.'),('Unzulässige Identitätsfolgerung erkannt.','Recognises the invalid identity inference.')]),
 case('puberty-physical-c2',('Verschiedene Entwicklungsverläufe','Different developmental courses'),'Fiktive gleichaltrige Personen A und B: A hatte schon einen Wachstumsschub und eine deutlich veränderte Stimme; bei B ist die Haut verändert und Körperhaarwuchs stärker, die Stimme bisher wenig. Eine Karte sagt, dass Pubertät nicht einheitlich abläuft und äußere Beobachtungen allein keine Diagnose ergeben. Eine Mitschülerin sagt: Wer zuerst größer ist, ist vollständiger entwickelt.','Fictional same-age people A and B: A has had a growth spurt and marked voice change; B has skin changes and more body hair but little voice change so far. A card says puberty follows different courses and external observations alone do not provide a diagnosis. A classmate says whoever becomes taller first is more completely developed.','Beschreibe die Unterschiede sachlich, benenne typische körperliche Pubertätsveränderungen und prüfe die behauptete Rangfolge.','Describe the differences factually, name typical physical changes in puberty and check the claimed ranking.','A zeigt Wachstum und Stimmveränderung, B Hautänderung und Körperhaarwuchs. Diese Veränderungen können verschieden ausgeprägt und zeitlich versetzt auftreten. Größe ist kein Gesamtmaß für Reife, Fortpflanzungsfähigkeit oder Identität. Die Rangfolge ist daher unbegründet. Bei wirklichen gesundheitlichen Fragen wäre verlässliche Beratung möglich; die Aufgabe diagnostiziert weder A noch B.','A shows growth and voice change; B shows skin changes and body hair. These may differ in expression and timing. Height is not an overall measure of maturity, reproductive capacity or identity. The ranking is therefore unjustified. Reliable advice is available for real health questions; the task diagnoses neither A nor B.','Eine neue Darstellung zeigt Brustentwicklung ohne Wachstumsschub zur gleichen Zeit. Ist sie zwingend falsch?','A new portrayal shows breast development without a growth spurt at the same time. Is it necessarily wrong?','Nein; unterschiedliche Abläufe sind möglich. Ein Schulbild zeigt Beispiele und ist kein verbindlicher Zeitplan für jede Person.','No; different courses are possible. A school picture shows examples and is not a mandatory timetable for everyone.',[('Veränderungen der Fälle korrekt beschrieben.','Correctly describes the changes in the cases.'),('Keine Rangfolge aus Größe, Variation begründet.','Rejects height ranking with a variation rationale.'),('Zeitfolgegrenze übertragen.','Transfers the timing limit.')])], 'Eine begrifflich-anschauliche Beschreibung körperlicher Pubertät; primär/sekundär sowie allgemeine Begleitveränderungen werden im selben Leistungsprodukt eingeordnet.')
row('a6f2bcaf','representation',[
 ('Befruchtung ist die Verschmelzung von Ei- und Samenzelle, normalerweise im Eileiter.','Fertilisation is fusion of egg and sperm, normally in the oviduct.','Ordnet Gameten, Ort und Entstehung der Zygote korrekt zu.','Correctly links gametes, location and formation of the zygote.'),
 ('Zellteilungen und Differenzierung führen über frühe Keimstadien zur Einnistung und weiteren Entwicklung.','Cell division and differentiation lead through early stages to implantation and further development.','Erklärt die zeitlich getrennte Abfolge und korrigiert Orts- oder Reihenfolgefehler.','Explains the temporally separated sequence and corrects location or order errors.'),
 ('Pränatale Versorgung erfolgt über getrennte Kreisläufe mit Stoffaustausch.','Prenatal supply occurs through separate circulations with substance exchange.','Begründet Versorgung und die Grenzen eines nicht maßstäblichen Entwicklungsbilds.','Explains supply and limits of a non-scale developmental picture.')], [('Zeitlich getrennte Stadien gegenüber Orten im Körper.','Separated developmental stages versus bodily locations.'),('Bildfehler und Modellgröße gegenüber Funktionszusammenhang.','Picture errors and model scale versus functional relationships.')],[
 case('reproduction-development-c1',('Orte und Entwicklungsfolge','Locations and developmental sequence'),'Fiktive Karten: Spermium und Eizelle verschmelzen normalerweise im Eileiter zur Zygote. Die Keimanlage teilt sich auf dem Weg zur Gebärmutter, ohne dass jedes frühe Teilungsstadium bereits proportional größer wird. Eine Blastozyste nistet sich in der Gebärmutterschleimhaut ein; danach folgen Organbildung und Wachstum. Ein fehlerhafter Pfeilplan lautet: Einnistung → Befruchtung in der Gebärmutter → Gameten → Geburt. Die Bildausschnitte im Material stellen vergrößerte, verschiedene Zeitpunkte dar, nicht mehrere gleichzeitige Embryonen.','Fictional cards: sperm and egg normally fuse in the oviduct to form a zygote. The conceptus divides on its way to the uterus without every early cleavage stage already becoming proportionally larger. A blastocyst implants in the uterine lining; organ formation and growth follow. An incorrect arrow plan reads implantation → fertilisation in the uterus → gametes → birth. The picture panels represent enlarged views at different times, not several simultaneous embryos.','Korrigiere den Pfeilplan mit Ort und Prozess und erkläre, wie Zellteilung, Einnistung und spätere Entwicklung zusammenhängen.','Correct the arrow plan using location and process and explain how cell division, implantation and later development relate.','Gameten → Befruchtung normalerweise im Eileiter → Zygote und frühe Zellteilungen → Blastozyste und Einnistung in der Gebärmutterschleimhaut → Embryonalentwicklung mit Organbildung → Fetalentwicklung mit Wachstum/Reifung → Geburt. Zellteilungen erhöhen die Zellzahl; spätere Differenzierung erzeugt unterschiedliche Zelltypen. Einnistung ist ein späterer Schritt als Befruchtung. Die getrennten Bilder sind Zeitstufen eines Konzepts und kein gleichzeitiger Mehrlingsbefund.','Gametes → fertilisation normally in the oviduct → zygote and early cleavage → blastocyst and implantation in the uterine lining → embryonic development with organ formation → fetal growth/maturation → birth. Cell division increases cell number; later differentiation generates different cell types. Implantation comes after fertilisation. The separate pictures are stages of a concept, not evidence of simultaneous multiple pregnancy.','Neu: In einem Bild wird die Blastozyste größer als ein späterer Embryo gezeichnet. Welche Schlussfolgerung ist möglich?','New: one picture draws a blastocyst larger than a later embryo. What can be concluded?','Bei ausdrücklich unterschiedlich vergrößerten Bildern keine biologische Größenabnahme ableiten. Die zeitliche Folge aus Prozessen prüfen; Größenvergleiche erfordern gleichen Maßstab.','With explicitly different magnifications, do not infer biological shrinkage. Check temporal order using processes; size comparison requires the same scale.',[('Gameten, Ort und korrekte vollständige Folge.','Gametes, location and correct complete sequence.'),('Zellteilung, Differenzierung und Einnistung erklärt.','Explains division, differentiation and implantation.'),('Zeitstufen und Maßstab sachlich unterschieden.','Factually distinguishes time stages and scale.')]),
 case('reproduction-development-c2',('Versorgung erklärt kein Vermischen','Supply does not imply blood mixing'),'Fiktives Entwicklungsmodell: Nach Einnistung bilden sich Versorgungsstrukturen. Die Plazenta ermöglicht Stoffaustausch zwischen mütterlichem und kindlichem Kreislauf; die Nabelschnur verbindet das Kind mit der Plazenta. Die Kreisläufe mischen sich normalerweise nicht direkt. Eine Lerngruppe behauptet: Der Embryo wächst, weil Blut der Mutter seine Organe direkt auffüllt; die Plazenta blockiert alles Schädliche. Die Darstellung ist schematisch und zeigt keine individuelle Messung.','Fictional developmental model: supply structures develop after implantation. The placenta enables substance exchange between maternal and fetal circulation; the umbilical cord connects the fetus with the placenta. The circulations normally do not mix directly. A group claims the embryo grows because maternal blood directly fills its organs and the placenta blocks everything harmful. The portrayal is schematic and shows no individual measurement.','Erkläre Wachstum und Versorgung und korrigiere beide Behauptungen mit einer Grenze des Modells.','Explain growth and supply and correct both claims with one model limit.','Wachstum und Organbildung beruhen auf Zellteilung, Größenzunahme und Differenzierung. Sauerstoff und Nährstoffe gelangen über Plazentaaustausch in den kindlichen Kreislauf; Abfallstoffe in Gegenrichtung. Mütterliches Blut füllt nicht direkt die kindlichen Organe, und die Plazenta hält nicht jede schädliche Substanz zurück. Ein Schulmodell ist weder Messung noch individuelle Gesundheitsprognose.','Growth and organ formation involve cell division, enlargement and differentiation. Oxygen and nutrients pass through placental exchange into fetal circulation; waste passes in the other direction. Maternal blood does not directly fill fetal organs, and the placenta does not block every harmful substance. A school model is neither a measurement nor an individual health prognosis.','Neu: Ein Schema lässt frühe Teilungsstadien aus und zeigt nur Zygote und Embryo. Ist das automatisch falsch?','New: a diagram omits early cleavage stages and shows only zygote and embryo. Is it automatically wrong?','Nicht automatisch; Vereinfachung ist erlaubt, wenn die Zwischenschritte erklärt und nicht zeitlich oder räumlich verdreht werden. Ein behaupteter unmittelbarer Sprung ohne Teilung wäre dagegen falsch.','Not automatically; simplification is permissible if intervening steps are explained and not reversed in time or location. A claim of an immediate jump without division would be wrong.',[('Wachstum mit Teilung und Differenzierung erklärt.','Explains growth through division and differentiation.'),('Versorgung, getrennte Kreisläufe und Plazentagrenze korrekt.','Correct supply, separate circulation and placental limits.'),('Vereinfachung von falscher Behauptung unterschieden.','Distinguishes simplification from a false claim.')])], 'Eine zusammenhängende Entwicklungsdarstellung von Gameten bis pränataler Versorgung; Orte und Stadien sind notwendige Aspekte desselben kausalen Leistungsprodukts.')
row('a6f57e17','concept',[
 ('Genuss oder häufige Nutzung allein sind keine Suchtdefinition; Kontrollverlust und Folgen sind wichtig.','Enjoyment or frequent use alone do not define addiction; loss of control and consequences matter.','Vergleicht konkrete Muster anhand von Kontrollierbarkeit und Schäden.','Compares concrete patterns using controllability and harm.'),
 ('Bewusstes Wahrnehmen von Risiken erlaubt freiwillige Reflexion ohne Ferndiagnose.','Awareness of risks permits voluntary reflection without remote diagnosis.','Benennt Warnzeichen und eine begründete Schutz- oder Hilfestrategie.','Names warning signs and a reasoned protective or help-seeking strategy.'),
 ('Eine einzelne Zeit-, Häufigkeits- oder Genussangabe gibt keine sichere Diagnose.','One time, frequency or enjoyment figure does not provide a certain diagnosis.','Überträgt Kriterien auf einen veränderten Fall und benennt die Informationsgrenze.','Transfers criteria to a changed case and states the information limit.')], [('Gleiche Dauer, verschiedene Kontrollierbarkeit und Folgen.','Equal duration, different controllability and consequences.'),('Alltagsgenuss gegenüber wiederholtem Handeln trotz Schaden.','Everyday enjoyment versus repeated behaviour despite harm.')],[
 case('enjoyment-boundary-c1',('Gleiche Zeit, andere Bedeutung','Same time, different meaning'),'Fiktive A und B spielen je etwa zwei Stunden an mehreren Tagen. A beendet zum vereinbarten Zeitpunkt, schläft ausreichend und pflegt Kontakte. B versucht wiederholt aufzuhören, spielt trotzdem weiter, versäumt wichtige Termine und leidet darunter. Die Materialkarte nennt starke Priorisierung, verminderte Kontrolle und Fortsetzen trotz negativer Folgen als Hinweise auf problematische Entwicklung; sie enthält keine Diagnose. Man muss keine eigene Nutzung offenlegen.','Fictional A and B each play around two hours on several days. A stops at the agreed time, sleeps adequately and maintains relationships. B repeatedly tries to stop but continues, misses important appointments and suffers. The card lists strong prioritisation, reduced control and continuing despite negative consequences as indicators of problematic development; it contains no diagnosis. Nobody must disclose their own use.','Erläutere die Grenze zwischen Genuss und möglicher Suchtentwicklung anhand der Fälle und formuliere eine freiwillig nutzbare Risikofrage mit einer Hilfemöglichkeit.','Explain the boundary between enjoyment and possible addiction development using the cases and formulate an optional risk-reflection question with a source of help.','Zeit allein unterscheidet die Fälle nicht. A zeigt kontrollierbaren Genuss ohne beschriebene Nachteile; B zeigt Kontrollprobleme und negative Folgen trotz Änderungsversuchen. Das sind ernstzunehmende Hinweise, keine abschließende Diagnose. Eine freiwillige Frage ist: Kann ich nach meinem Plan aufhören, und leiden wichtige Lebensbereiche? Bei anhaltenden Problemen kann eine vertraute Person oder fachliche Beratung helfen, ohne jemanden zu beschämen.','Time alone does not distinguish the cases. A shows controllable enjoyment without described harm; B shows control problems and negative consequences despite attempts to change. These are important indicators, not a final diagnosis. An optional question is: can I stop according to my plan, and are important areas of life suffering? Persistent problems may warrant help from a trusted person or professional advice without shaming anyone.','Neu: A spielt einmal länger bei einer gemeinsam geplanten Veranstaltung, ohne die übrigen Angaben zu verändern.','New: A plays longer once at a jointly planned event, with the other facts unchanged.','Eine einzelne längere Nutzung beweist keine Sucht. Kontrollierbarkeit, Dauerhaftigkeit und Folgen im Zusammenhang prüfen; ein Etikett aus einer Zeitangabe vermeiden.','One longer occasion does not prove addiction. Consider controllability, persistence and consequences together; avoid a label based on one time figure.',[('Gleiche Zeit anhand Kontrolle und Folgen differenziert.','Differentiates equal time using control and consequences.'),('Warnzeichen und freiwillige Hilfe ohne Diagnose.','Warning signs and optional help without diagnosis.'),('Einzelereignis sachlich übertragen.','Factually transfers to a single event.')]),
 case('enjoyment-boundary-c2',('Moralisches Etikett prüfen','Checking a moral label'),'Fiktive Aussagen: C genießt Musik, kann Pausen machen und verliert keine wichtigen Aktivitäten. D nimmt wiederholt eine Substanz trotz belastender Folgen und eigener Begrenzungsversuche; über Häufigkeit und Gesundheit liegen nur diese Angaben vor. Ein Kommentar lautet: Wer etwas genießt, ist bereits süchtig; Betroffene müssen nur stärker sein. Die Karte beschreibt Sucht als komplexe Entwicklung und Beratung als Unterstützung, nicht Strafe.','Fictional statements: C enjoys music, can take breaks and loses no important activities. D repeatedly uses a substance despite distressing consequences and attempts to limit use; these are the only frequency and health facts available. A comment says everyone enjoying something is already addicted and affected people only need to be stronger. The card describes addiction as a complex development and counselling as support, not punishment.','Beurteile beide Kommentarteile, erläutere relevante Risikokriterien und eine verantwortungsvolle Reaktion.','Assess both parts of the comment, explain relevant risk criteria and a responsible response.','Genuss allein definiert keine Sucht; C zeigt keine beschriebenen Kontroll- oder Schadenshinweise. Bei D sind Fortsetzung trotz Folgen und misslingende Begrenzung relevant, reichen hier aber nicht für eine klinische Diagnose. Ein Willensschwächeurteil erklärt die komplexe Entwicklung nicht. Eine verantwortungsvolle Reaktion benennt Beobachtungen respektvoll und bietet Hilfe an; sie verordnet keinen eigenständigen Entzug.','Enjoyment alone does not define addiction; C has no described indicators of control loss or harm. For D, continuing despite consequences and failed limits matter but do not establish a clinical diagnosis here. A weak-will judgement does not explain complex development. A responsible response states observations respectfully and offers help; it does not prescribe unsupervised withdrawal.','Übertrage auf eine Person, die sich um die eigene Nutzung sorgt, aber nichts Persönliches berichten möchte.','Transfer to a person concerned about their use who does not want to disclose anything personal.','Privatsphäre respektieren. Allgemeine Kriterien und freiwillige vertrauliche Beratung anbieten, keine Offenlegung als Nachweis verlangen und keine Diagnose aus Schweigen ableiten.','Respect privacy. Offer general criteria and voluntary confidential advice, require no disclosure as proof and infer no diagnosis from silence.',[('Genuss und mögliche problematische Entwicklung unterschieden.','Distinguishes enjoyment from possible problematic development.'),('Moralisches Etikett widerlegt und Hilfe begrenzt.','Refutes the moral label and bounds the help.'),('Privatsphäre beim Transfer erhalten.','Preserves privacy in transfer.')])], 'Eine kriterienbezogene Grenzerläuterung samt freiwilliger Risikoreflexion, keine private Selbstdiagnose oder separate Persönlichkeitsprüfung.')
row('d6727804','procedure',[
 ('Respektvolle Kommunikation nutzt passende Fachsprache und schützt die Würde und Privatsphäre.','Respectful communication uses appropriate terminology and protects dignity and privacy.','Formuliert konkrete respektvolle Aussagen für medizinische, gesellschaftliche und partnerschaftliche Kontexte.','Formulates concrete respectful statements for medical, social and partnership contexts.'),
 ('Abwertende oder sexualisierte Grenzverletzung ist nicht durch Humor oder frühere Zustimmung gerechtfertigt.','Degrading or sexual boundary violations are not justified by humour or earlier consent.','Erkennt die Grenzverletzung und formuliert eine sichere angemessene Reaktion.','Recognises the violation and formulates a safe appropriate response.'),
 ('Unterstützung kann die betroffene Person entlasten, ohne sie zur Konfrontation oder Offenlegung zu zwingen.','Support can help the affected person without forcing confrontation or disclosure.','Überträgt Sprache und Hilfeschritte auf ein neues Medium.','Transfers language and help-seeking steps to a new medium.')], [('Medizinisches Gespräch, gesellschaftliche Diskussion und Partnerschaft.','Medical conversation, public discussion and partnership.'),('Direkte Sprache gegenüber digital vermittelter Belästigung.','Direct speech versus digitally mediated harassment.')],[
 case('respectful-communication-c1',('Drei Kontexte, respektvolle Sprache','Three contexts, respectful language'),'Fiktive Gesprächsanfänge: In einer Praxis wird gefragt, wie man eine Sorge um die eigene Gesundheit sachlich ansprechen kann. In einer öffentlichen Diskussion wird eine Person wegen ihrer Orientierung abgewertet. In einer Partnerschaft möchte eine erwachsene Person eine Berührung nicht. Eine Karte schlägt sachliche Begriffe wie Geschlechtsorgane oder Infektionsschutz, Ich-Aussagen, freiwillige Grenzen und Verzicht auf Spott vor. Niemand muss in dieser Aufgabe eigene Erfahrungen berichten.','Fictional conversation openings: at a clinic someone asks how to raise a health concern factually. In a public discussion someone is demeaned because of their orientation. In a partnership an adult does not want a touch. A card proposes factual terms such as reproductive organs or infection prevention, I-statements, voluntary boundaries and avoiding ridicule. Nobody must disclose personal experience in this task.','Formuliere für jeden Kontext eine passende respektvolle Aussage und erkläre gemeinsam, wie Sprache Würde und Selbstbestimmung schützt.','Formulate an appropriate respectful statement for each context and jointly explain how language protects dignity and self-determination.','Praxis: Ich habe eine Frage zum Infektionsschutz und möchte sie vertraulich besprechen. Diskussion: Orientierung rechtfertigt keine Abwertung; wir können sachlich sprechen, ohne Menschen zu beleidigen. Partnerschaft: Ich möchte diese Berührung nicht; bitte respektiere meine Grenze. Sachliche, situationspassende Sprache ermöglicht Information und klare Wünsche. Privatsphäre und Ablehnung respektieren, keine Erklärung erzwingen.','Clinic: I have a question about infection prevention and would like to discuss it confidentially. Discussion: orientation does not justify demeaning someone; we can speak factually without insulting people. Partnership: I do not want this touch; please respect my boundary. Factual, context-appropriate language enables information and clear wishes. Respect privacy and refusal without forcing an explanation.','Neu: Die Ablehnung wird in einer Sprachnachricht als unhöflich verspottet.','New: the refusal is ridiculed as rude in a voice message.','Eine Grenze bleibt auch im neuen Medium gültig. Eine ruhige Antwort kann sie bekräftigen; bei fortgesetztem Druck Unterstützung suchen. Die betroffene Person muss keine Diskussion führen, um Ablehnung gültig zu machen.','A boundary remains valid in the new medium. A calm response may reaffirm it; seek support if pressure persists. The affected person need not enter a debate to make refusal valid.',[('Drei situationsgerechte konkrete Aussagen.','Three concrete context-appropriate statements.'),('Sprache, Würde und Grenze zusammen erklärt.','Explains language, dignity and boundaries together.'),('Medienwechsel ohne Relativierung der Ablehnung.','Media transfer without relativising refusal.')]),
 case('respectful-communication-c2',('Auf digitale Belästigung reagieren','Responding to digital harassment'),'Fiktiver Gruppenchat enthält einen abwertenden sexualisierten Kommentar über eine Person und eine Forderung nach privaten Bildern. Die betroffene Person möchte nicht öffentlich antworten. Eine Materialkarte nennt: Grenzen respektieren, Unterstützung durch vertrauenswürdige Erwachsene oder eine Beratungsstelle, Melde- und Blockierfunktionen, keine beschuldigenden Fragen und keine Weiterverbreitung privater oder belästigender Bilder. Bei akuter Gefahr steht Schutz im Vordergrund.','A fictional group chat contains a degrading sexualised comment about someone and a demand for private pictures. The affected person does not want to reply publicly. A card lists respecting boundaries, support from trusted adults or counselling, reporting and blocking tools, no accusatory questions, and no redistribution of private or harassing images. In immediate danger, safety comes first.','Entwirf eine respektvolle Nachricht an die betroffene Person und zwei angemessene Handlungen. Begründe, warum öffentliche Konfrontation und Weiterleitung keine Pflicht sind.','Draft a respectful message to the affected person and two appropriate actions. Explain why public confrontation and forwarding content are not obligations.','Nachricht: Das war nicht in Ordnung und nicht deine Schuld. Du musst nicht öffentlich antworten; ich kann dich beim Suchen von Unterstützung begleiten. Geeignete Schritte sind Melden/Blockieren soweit sicher und vertrauliche Hilfe bei einer vertrauenswürdigen erwachsenen Person oder Beratungsstelle. Private Inhalte nicht weiterverteilen; nötige Dokumentation nur geschützt mit zuständiger Unterstützung klären. Die Verantwortung liegt bei der grenzverletzenden Person, nicht bei einer ausbleibenden Antwort.','Message: that was not okay and not your fault. You do not have to reply publicly; I can support you in finding help. Suitable steps include reporting or blocking where safe and confidential help from a trusted adult or counselling service. Do not redistribute private content; clarify any necessary documentation securely with appropriate support. Responsibility lies with the person violating the boundary, not with the absence of a reply.','Neue Variation: Der gleiche Kommentar fällt in einem persönlichen Gespräch; die Person möchte die Situation verlassen.','New variation: the same comment is made in person and the affected person wants to leave.','Den Wunsch unterstützen, Abstand und sichere Begleitung ermöglichen und anschließend vertrauliche Hilfe anbieten. Nicht zu einer Diskussion oder Beweisführung vor der Gruppe drängen.','Support the wish, enable distance and safe accompaniment, and later offer confidential help. Do not pressure the person into debating or proving the case before the group.',[('Respektvolle Nachricht ohne Opferbeschuldigung.','Respectful message without victim blaming.'),('Zwei sichere angemessene Schritte ohne Weiterverbreitung.','Two safe appropriate steps without redistribution.'),('Persönlicher Kontext mit freiwilliger Grenze übertragen.','Transfers to an in-person context preserving voluntary boundaries.')])], 'Ein konkreter respektvoller Kommunikations-/Reaktionsprozess mit Varianten in drei Kontexten, kein Bündel aus Diagnostik, Rechtswissen und Persönlichkeitsbewertung.')
MEMORY_REASONS={
 '0e1065b9':('Problemlösen, Stressbewältigung und Beziehungsfähigkeit werden in neuen Alltagssituationen begründet kombiniert. Begriffskarten würden keinen Entwicklungsplan nachweisen.','Problem-solving, stress coping and relationship skills are combined with reasons in new everyday situations. Term cards would not establish a development plan.'),
 '17dc9671':('Die Leistung bewertet begrenzt Risiken und begründet professionelle Rücksprache anhand von Material. Eine Abrufliste würde daraus weder eine individuelle Risikobewertung noch sichere Medikamentenberatung machen.','The performance bounds risks and justifies professional consultation using material. A recall list would establish neither an individual risk assessment nor safe medication advice.'),
 '3c0f5267':('Entwicklung, Selbstbild und Medienansprüche werden gemeinsam in einem neuen Fall eingeordnet. Normale Unterschiede müssen begründet werden; eine Merkmalsliste genügt nicht.','Development, self-image and media expectations are interpreted together in a new case. Normal variation must be explained; a feature list is insufficient.'),
 '63856e48':('Die Materialkarten liefern Erregerwege und Schutzoptionen; verlangt ist die passende begründete Präventionsentscheidung mit Grenzen. Kartenabruf allein belegt diese Übertragung nicht.','Material cards supply transmission routes and protective options; the demand is an appropriate reasoned prevention decision with limits. Card recall alone does not demonstrate that transfer.'),
 '6add2bde':('Selbstbestimmung und Medienwirkung werden auf neue fiktive Situationen angewandt. Respekt und kontextspezifische Zustimmung sind zu begründen, keine auswendig gelernte Zustimmungsschablone.','Self-determination and media effects are applied to new fictional situations. Respect and context-specific consent require reasons, not a memorised consent template.'),
 '6de6ad3b':('Gesundheitskriterien, Alternativen und Bedingungen werden im Einzelfall gegeneinander abgewogen. Eine Liste vermeintlich guter Gewohnheiten würde die begründete Entscheidung nicht nachweisen.','Health criteria, alternatives and conditions are weighed in individual cases. A list of supposedly good habits would not demonstrate the reasoned decision.'),
 '773a297d':('Ein mehrfaktorielles Ursachen- und Rückkopplungsmodell wird am Material erläutert und auf neue Bedingungen übertragen. Einzelwortabruf beweist weder den Mechanismus noch seine Grenzen.','A multifactorial causal and feedback model is explained using material and transferred to new conditions. Isolated term recall establishes neither the mechanism nor its limits.'),
 '848334f3':('Zeitliche Entwicklungs- und Geburtszusammenhänge und begrenzte Risiken werden mit bereitgestellten Karten erklärt. Reihenfolgeabruf allein wäre kein Prozessverständnis; neue Darstellungen müssen begründet werden.','Temporal developmental and birth relationships and bounded risks are explained using supplied cards. Sequence recall alone would not establish process understanding; new representations require explanation.'),
 '91f62a7b':('Körperliche Merkmale werden am Material primär/sekundär eingeordnet und normale individuelle Unterschiede begründet. Die Kategorien stehen im Material; Transfer statt zusätzliche Merkmalskarten zählt.','Physical features are classified as primary or secondary using material and normal individual variation is explained. Categories are supplied in the material; transfer matters rather than additional feature cards.'),
 'a6f2bcaf':('Orte, Zellprozesse und Zeitstufen werden in fehlerhaften und veränderten Darstellungen kausal verknüpft. Begriffs- oder Reihenfolgekarten allein würden diese Fehlerkorrektur nicht nachweisen.','Locations, cellular processes and time stages are causally connected in flawed and changed representations. Term or sequence cards alone would not establish that correction.'),
 'a6f57e17':('Kontrolle, Folgen und Hilfemöglichkeiten werden anhand gleicher Nutzungszeiten und neuer Situationen abgegrenzt. Kriteriensätze auswendig zu kennen wäre weder die Fallbegründung noch eine Diagnose.','Control, consequences and support are distinguished using equal use durations and new situations. Memorised criteria would establish neither case reasoning nor a diagnosis.'),
 'd6727804':('Die Leistung erzeugt kontextgerechte respektvolle Antworten und sichere Handlungsvorschläge. Eine Liste netter Formulierungen würde den Kommunikationsprozess und die Grenzwahrung nicht nachweisen.','The performance creates context-appropriate respectful responses and safe action proposals. A list of polite phrases would not establish the communication process or respect for boundaries.'),
}
for r in ROWS:
 de,en=MEMORY_REASONS[r['goalId'][:8]]
 r['memoryAuthorDecision']={'decision':'no_memory_needed','reasonDe':de,'reasonEn':en,'cardsRequired':False,'cardOrVisibilityChanges':False,'currentGoalHasMemorizationOrDeckTag':any(t=='memorization' or t.startswith('srs-deck:') for t in r['wholeCurrentGoal'].get('tags',[])),'authority':'AUTHOR individual candidate; independent Memory review pending'}
assert len(ROWS)==12 and {r['goalId'] for r in ROWS}=={g['id'] for g in GOALS}
d=dict(schemaVersion=1,role='Own AUTHOR candidates only; independent D/P/A/M/V reviews pending',createdAt=datetime.now(timezone.utc).isoformat(),reviewId=RID,reviewerAgent='/root/chemistry_rollout_report_review (AUTHOR for this disjoint Bio12)',goalIds=[r['goalId'] for r in ROWS],wholeGoalsAndProfilesAndCases=ROWS,humanApproval=False,humanTrial=False,actualExperimentPerformed=False,strictGain=0,contentLicense='CC-BY-4.0')
(B/'science/twelve-whole-profiles-and-twenty-four-cases.author.json').write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
p=dict(schemaVersion=1,authoringContract='positive-understanding-evidence-candidates-v1',reviewId=RID,reviewedAt=d['createdAt'],reviewer=d['reviewerAgent'],goals=[{k:r[k] for k in ['goalId','reason','evidenceLevel','maximumClaimScope','profile']}|{'dissent':[]} for r in ROWS])
(B/'science/twelve-positive-candidate-set.author.json').write_text(json.dumps(p,ensure_ascii=False,indent=2)+'\n')
print(json.dumps({'goals':len(ROWS),'cases':sum(len(r['wholeMaterialCases']) for r in ROWS),'expectations':sum(len(r['profile']['expectations']) for r in ROWS),'approved':0,'strictGain':0}))
